From 71fc9a3ca120a2c9f30b0b928d74abd5f09fe72b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sun, 22 Nov 2026 01:10:02 +0100
Subject: [PATCH] http: report a connection that breaks during the response
 body

Network errors were only mapped when no HTTP status had arrived yet, so
a connection dropped after the headers ended the transfer successfully
with truncated data. Now it fails with ERR_CONNECTION_BROKEN instead.

BUG: 518488
---
 src/kioworkers/http/http.cpp | 4 ++++
 1 file changed, 4 insertions(+)

diff --git a/src/kioworkers/http/http.cpp b/src/kioworkers/http/http.cpp
index eb5b927ff..d3abd3843 100644
--- a/src/kioworkers/http/http.cpp
+++ b/src/kioworkers/http/http.cpp
@@ -624,6 +624,10 @@ HTTPProtocol::Response HTTPProtocol::makeRequest(const QUrl &url,
     });

     const int statusCode = reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();
+    // A network error after the response headers means the connection broke while the body was coming in
+    if (statusCode != 0 && reply->error() > QNetworkReply::NoError && reply->error() <= QNetworkReply::UnknownNetworkError) {
+        return {0, QByteArray(), KIO::ERR_CONNECTION_BROKEN};
+    }
     if (reply->error() != QNetworkReply::NoError && statusCode == 0) {
         // anything not listed here gets KIO::ERR_CANNOT_CONNECT
         static constexpr const std::pair<QNetworkReply::NetworkError, int> qnam2kio_errors[] = {
